function classifyStatementLine(line) {
    if (line.trim() === "") {
        return "blank";
    }
    if (isHeading(line)) {
        return "heading";
    }
    if (isTableRow(line)) {
        return "table";
    }
    if (isListItem(line)) {
        return "list-item";
    }
    return "paragraph";
}
/** Line-by-line statement accumulator behind `segmentStatements`. */
class StatementAccumulator {
    statements = [];
    ordinal = 0;
    currentHeading = null;
    inFence = false;
    paragraphLines = [];
    paragraphStartLine = 0;
    flushParagraph() {
        if (this.paragraphLines.length === 0) {
            return;
        }
        const para = this.paragraphLines.join(" ");
        const startLine = this.paragraphStartLine;
        this.paragraphLines = [];
        for (const sentence of splitSentences(para)) {
            this.statements.push({
                ordinal: this.ordinal++,
                text: sentence,
                kind: "sentence",
                enclosingHeading: this.currentHeading,
                line: startLine,
            });
        }
    }
    pushListItemStatement(text, line) {
        if (!text) {
            return;
        }
        this.statements.push({
            ordinal: this.ordinal++,
            text,
            kind: "list-item",
            enclosingHeading: this.currentHeading,
            line,
        });
    }
    appendParagraphLine(line, lineNumber) {
        if (this.paragraphLines.length === 0) {
            this.paragraphStartLine = lineNumber;
        }
        this.paragraphLines.push(line.trim());
    }
    actionHandlers = {
        blank: (_lines, i) => {
            this.flushParagraph();
            return i;
        },
        heading: (_lines, i, line) => {
            this.flushParagraph();
            this.currentHeading = parseHeading(line);
            return i;
        },
        table: (_lines, i) => {
            this.flushParagraph();
            return i;
        },
        "list-item": (lines, i) => {
            this.flushParagraph();
            const itemStartLine = i + 1;
            const listItem = readListItemLines(lines, i);
            this.pushListItemStatement(listItem.combined, itemStartLine);
            return listItem.endIndex;
        },
        paragraph: (_lines, i, line) => {
            this.appendParagraphLine(line, i + 1);
            return i;
        },
    };
    /** Processes the line at index `i`; returns the index the outer loop should resume from (before its own `i++`). */
    processLine(lines, i) {
        const line = lines[i];
        if (/^\s*```/.test(line)) {
            this.flushParagraph();
            this.inFence = !this.inFence;
            return i;
